def max_value_on_paths(N: int, grid_values: List[Tuple[int, int, int]]) -> int:
    grid = [[0] * N for _ in range(N)]
    for x, y, value in grid_values:
        if x == 0 and y == 0 and value == 0:
            break
        grid[x-1][y-1] = value

    dp = [[[-float('inf')] * N for _ in range(N)] for _ in range(N)]
    dp[0][0][0] = grid[0][0]

    for i1 in range(N):
        for j1 in range(N):
            for i2 in range(i1, N):
                j2 = i1 + j1 - i2
                if j2 < 0 or j2 >= N or grid[i1][j1] == -1 or grid[i2][j2] == -1:
                    continue
                cur = dp[i1][j1][i2]
                if i1 > 0:
                    cur = max(cur, dp[i1-1][j1][i2])
                if j1 > 0:
                    cur = max(cur, dp[i1][j1-1][i2])
                if i2 > 0:
                    cur = max(cur, dp[i1][j1][i2-1])
                if j2 > 0 and i1 != i2:
                    cur = max(cur, dp[i1][j1][i2][j2-1])
                if cur == -float('inf'):
                    continue
                cur += grid[i1][j1]
                if i1 != i2:
                    cur += grid[i2][j2]
                dp[i1][j1][i2] = cur

    return max(0, dp[N-1][N-1][N-1])

def max_value_on_paths(N: int, grid_values: List[Tuple[int, int, int]]) -> int:
    # Initialize the grid with zeros
    grid = [[0] * N for _ in range(N)]

    # Fill the grid with the given values
    for x, y, value in grid_values:
        if x == 0 and y == 0 and value == 0:
            break
        grid[x-1][y-1] = value

    # Initialize the DP table
    dp = [[[-1] * (N + 1) for _ in range(N + 1)] for _ in range(N + 1)]
    dp[1][1][1] = grid[0][0]

    # Fill the DP table
    for i in range(1, N + 1):
        for j in range(1, N + 1):
            for k in range(1, min(N + 1, i + j)):
                l = j + i - k
                if l < 1 or l > N:
                    continue
                if dp[i][j][k] == -1 or dp[i-1][j][k] == -1 or dp[i][j-1][k] == -1 or dp[i-1][j-1][k-1] == -1:
                    continue
                val1 = grid[i-1][k-1]
                val2 = grid[j-1][l-1]
                if k == l:
                    dp[i][j][k] = max(dp[i][j][k], dp[i-1][j][k] + val1, dp[i][j-1][k] + val1, dp[i-1][j-1][k-1] + val1)
                else:
                    dp[i][j][k] = max(dp[i][j][k], dp[i-1][j][k] + val1 + val2, dp[i][j-1][k] + val1 + val2, dp[i-1][j-1][k-1] + val1 + val2)

    # The result is the maximum value in dp[N][N][1] to dp[N][N][N]
    return max(dp[N][N][k] for k in range(1, N + 1))

def max_value_on_paths(N: int, grid_values: List[Tuple[int, int, int]]) -> int:
    # Create a grid to store the values
    grid = [[0] * N for _ in range(N)]
    for x, y, value in grid_values:
