    # Initialize the DP table
    dp = [[[-float('inf')] * N for _ in range(N)] for _ in range(N)]
    dp[0][0][0] = grid[0][0]

    # Fill the DP table
    for i in range(N):
        for j in range(N):
            for k in range(N):
                l = i + j - k
                if l < 0 or l >= N or grid[i][j] == -1 or grid[k][l] == -1:
                    continue
                if i > 0:
                    dp[i][j][k] = max(dp[i][j][k], dp[i-1][j][k])
                if j > 0:
                    dp[i][j][k] = max(dp[i][j][k], dp[i][j-1][k])
                if k > 0:
                    dp[i][j][k] = max(dp[i][j][k], dp[i][j][k-1])
                if l > 0:
                    dp[i][j][k] = max(dp[i][j][k], dp[i][j][k-1] if k > 0 else -float('inf'))
                dp[i][j][k] += grid[i][j]
                if i != k or j != l:
                    dp[i][j][k] += grid[k][l]

    return max(0, dp[N-1][N-1][N-1])

