def find_number_combinations():
    def is_unique_digits(n1, n2, n3):
        digits = str(n1) + str(n2) + str(n3)
        return len(set(digits)) == len(digits) and '0' not in digits

    combinations = []
    for first in range(123, 334):  # 123 is the smallest 3-digit number starting with 1, 333 is the largest with unique digits * 3
        second = first * 2
        third = first * 3
        if is_unique_digits(first, second, third) and 999 >= second >= 100 and 999 >= third >= 100:
            combinations.append((first, second, third))

    return sorted(combinations)

def find_number_combinations():
    result = []
    for first_digit in range(1, 9):
        for second_digit in range(0, 10):
            if second_digit == first_digit:
                continue
            for third_digit in range(0, 10):
                if third_digit == first_digit or third_digit == second_digit:
                    continue
                first_number = first_digit * 100 + second_digit * 10 + third_digit
                second_number = first_number * 2
                third_number = first_number * 3

                if second_number > 999 or third_number > 999:
                    continue

                second_number_digits = [int(d) for d in str(second_number)]
                third_number_digits = [int(d) for d in str(third_number)]

                if len(set(second_number_digits)) != 3 or len(set(third_number_digits)) != 3:
                    continue

                if len(set.union(set([first_digit, second_digit, third_digit]), set(second_number_digits), set(third_number_digits))) == 9:
                    result.append((first_number, second_number, third_number))

    return sorted(result)

def find_number_combinations():
    def is_unique(n1, n2, n3):
        digits = str(n1) + str(n2) + str(n3)
        return len(set(digits)) == len(digits)

    combinations = []
    for num in range(123, 334):  # 334 is chosen because 3 * 333 = 999, and we need 3 unique digits
        first = num
        second = 2 * num
        third = 3 * num
        if second > 999 or third > 999:
            break
        if is_unique(first, second, third):
            combinations.append((first, second, third))

    return combinations

