def max_product(num_str: str, N: int, K: int) -> int:
    def helper(start, k):
        if k == 0:
            return int(num_str[start:])
        max_product = 0
        for i in range(start + 1, N - k + 1):
            current_product = int(num_str[start:i]) * helper(i, k - 1)
            max_product = max(max_product, current_product)
        return max_product

    return helper(0, K)

def max_product(num_str: str, N: int, K: int) -> int:
    def split_number(nums, k):
        if k == 0:
            return int(''.join(nums))
        max_product = 0
        for i in range(1, len(nums) - (k - 1)):
            left = int(''.join(nums[:i]))
            right = split_number(nums[i:], k - 1)
            max_product = max(max_product, left * right)
        return max_product

    return split_number(list(num_str), K)

