def max_product(num_str: str, N: int, K: int) -> int:
    def split_and_multiply(parts):
        product = 1
        for part in parts:
            product *= int(part)
        return product

    def backtrack(start, k, current_parts):
        if k == 0:
            current_parts.append(num_str[start:])
            max_product = split_and_multiply(current_parts)
            current_parts.pop()
            return max_product
        max_val = 0
        for end in range(start + 1, N - k + 2):
            current_parts.append(num_str[start:end])
            max_val = max(max_val, backtrack(end, k - 1, current_parts))
            current_parts.pop()
        return max_val

    return backtrack(0, K, [])

