                value = int(char)
            total += (10 - i) * value
        checksum = 11 - (total % 11)
        return 'X' if checksum == 10 else str(checksum) if checksum != 11 else '0'

    original_checksum = isbn[-1]
    calculated_checksum = calculate_checksum(isbn[:-1])
    if original_checksum == calculated_checksum:
        return "Right"
