        parts = isbn.split('-')
        digits = ''.join(parts[:-1]) + parts[-1].replace('X', '10')
        total = sum((i + 1) * int(digits[i]) for i in range(10))
        checksum = total % 11
        return 'X' if checksum == 10 else str(checksum)

    provided_checksum = isbn[-1]
    correct_checksum = calculate_checksum(isbn[:-1] + '0')

    if provided_checksum == correct_checksum:
        return "Right"
    else:
        return isbn[:-1] + correct_checksum

