    for i, coeff in enumerate(coeffs):
        degree = n - i
        if coeff == 0:
            continue
        sign = '-' if coeff < 0 else '+'
        if i == 0:
            sign = ''  # No leading '+' sign
        abs_coeff = abs(coeff)
        if abs_coeff == 1 and degree > 0:
            coeff_str = ''
