def preorder_traversal(inorder: str, postorder: str) -> str:
    if not inorder or not postorder:
        return ""

    root = postorder[-1]
    root_index = inorder.index(root)

    left_inorder = inorder[:root_index]
    right_inorder = inorder[root_index + 1:]

    left_postorder = postorder[:len(left_inorder)]
    right_postorder = postorder[len(left_inorder):-1]

    return root + preorder_traversal(left_inorder, left_postorder) + preorder_traversal(right_inorder, right_postorder)

def string_transformation(A: str, B: str, rules: list) -> Union[int, str]:
    from collections import deque

    if A == B:
        return 0

    queue = deque([(A, 0)])
    visited = set([A])

    while queue:
        current, steps = queue.popleft()

        if steps >= 10:
            continue

        for src, target in rules:
            start = 0
            while start < len(current):
                pos = current.find(src, start)
                if pos == -1:
                    break
                new_string = current[:pos] + target + current[pos+len(src):]
                if new_string == B:
                    return steps + 1
                if new_string not in visited:
                    visited.add(new_string)
                    queue.append((new_string, steps + 1))
                start = pos + 1

    return "NO ANSWER!"

