    # Convert the number to a string for easier manipulation
    original_number = str(n)
    # Create a set to store unique numbers
    unique_numbers = set([original_number])
    # Create a queue for BFS and initialize it with the original number
    queue = deque([original_number])

    # Create a dictionary to store the transformation rules for quick lookup
    transformation_dict = {}
    for x, y in rules:
        if x not in transformation_dict:
            transformation_dict[x] = set()
        transformation_dict[x].add(y)

    # Perform BFS
    while queue:
        current_number = queue.popleft()
        for i in range(len(current_number)):
            digit = int(current_number[i])
            if digit in transformation_dict:
                for transformed_digit in transformation_dict[digit]:
                    new_number = current_number[:i] + str(transformed_digit) + current_number[i+1:]
                    if new_number not in unique_numbers:
                        unique_numbers.add(new_number)
                        queue.append(new_number)

    # Return the count of unique numbers
    return len(unique_numbers)

