    for speaker, stmts in statements.items():
        for stmt in stmts:
            if any(day in stmt for day in days_of_week):
                continue  # Ignore statements about the day of the week
            if speaker in liar_count:
                # If the speaker is a liar, their statement should be false
                if scenario in stmt and "not guilty" in stmt:
                    return False
                if scenario not in stmt and "guilty" in stmt:
                    return False
            else:
                # If the speaker is not a liar, their statement should be true
                if scenario in stmt and "guilty" not in stmt:
                    return False
                if scenario not in stmt and "not guilty" not in stmt:
                    return False
    return True

