def vigenere_decrypt(key: str, ciphertext: str) -> str:
    def shift_char(c, k):
        if c.islower():
            start = ord('a')
        else:
            start = ord('A')
        return chr(start + (ord(c) - start - (ord(k) - ord('A'))) % 26)

    key_length = len(key)
    key_as_int = [ord(i) for i in key]
    ciphertext_int = [ord(i) for i in ciphertext]
    plaintext = ''

    for i in range(len(ciphertext_int)):
        value = (ciphertext_int[i] - key_as_int[i % key_length]) % 26
        plaintext += chr(value + 65) if ciphertext[i].isupper() else chr(value + 97)

    return plaintext.lower()

def vigenere_decrypt(key: str, ciphertext: str) -> str:
    def shift_char(c, k):
        if c.islower():
            return chr((ord(c) - ord(k) + 26) % 26 + ord('a'))
        else:
            return chr((ord(c) - ord(k) + 26) % 26 + ord('A'))

    key = key.lower()
    decrypted_text = []
    key_index = 0
    key_length = len(key)

    for char in ciphertext:
        if char.isalpha():
            k = key[key_index % key_length]
            decrypted_text.append(shift_char(char, k))
            key_index += 1
        else:
            decrypted_text.append(char)

    return ''.join(decrypted_text)

