def jinjin_savings_plan(budgets: List[int]) -> int:
    pocket_money_per_month = 300
    savings_rate = 100
    interest_rate = 1.20
    total_savings = 0

    for month in range(12):
        remaining = pocket_money_per_month - budgets[month]
        if remaining < savings_rate:
