    if n <= 2:
        return 0

    left_peak = [0] * n
    right_peak = [0] * n

    current_max = heights[0]
    for i in range(1, n):
        if heights[i] > current_max:
            current_max = heights[i]
            left_peak[i] = left_peak[i - 1]
        else:
            left_peak[i] = left_peak[i - 1] + 1

    current_max = heights[-1]
